use vstd::prelude::*;

verus! {

fn linear_search(a: &Vec<i32>, e: i32) -> (r: usize)
    ensures
        // Result is always in-bounds or exactly len (not found).
        r <= a.len(),

        // If we return an index inside the array, it points to an occurrence of e,
        // and it is the first occurrence.
        r < a.len() ==> a[r as int] == e,
        r < a.len() ==> (forall |j: int| 0 <= j < r as int ==> a[j] != e),

        // If we return len, then e does not occur in the array.
        r == a.len() ==> (forall |j: int| 0 <= j < a.len() as int ==> a[j] != e),
{
    for (i, &x) in a.iter().enumerate()
        invariant
            // i is always a valid prefix length
            i <= a.len(),

            // no match has been seen so far in the prefix [0, i)
            forall |j: int| 0 <= j < i as int ==> a[j] != e,
    {
        if x == e {
            // Establish that the found index is indeed an occurrence and is first.
            assert(a[i as int] == e);
            assert(forall |j: int| 0 <= j < i as int ==> a[j] != e);
            return i;
        }
    }

    // Loop finished: no match in [0, len)
    assert(forall |j: int| 0 <= j < a.len() as int ==> a[j] != e);
    a.len()
}

} // verus!

